package com.fitnutri.backend.records.food;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.ProfileService;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.submission.*;
import com.fitnutri.backend.support.*;
import com.fitnutri.backend.user.*;
import java.math.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;
class FoodEntryReadIT extends PostgresIntegrationSupport {
 @Autowired FoodEntryReadService reads;@Autowired FoodEntryV2Service create;@Autowired FoodEntryPreviewService previews;@Autowired FoodEntryMutationService mutations;@Autowired UserRepository users;@Autowired ProfileService profiles;@Autowired FoodReferenceRepository references;@Autowired FoodDatasetRepository datasets;@Autowired JdbcTemplate jdbc;
 User owner;FoodReference ref;SubmissionReceiptV2Response proof;final LocalDate date=LocalDate.of(2020,1,2);
 @BeforeEach void setup(){owner=FoodV2TestFixtures.owner(users,profiles);ref=FoodV2TestFixtures.reference(datasets,references,"1000");var single=new FoodEntryInputs.Single(UUID.randomUUID(),ref.getId().toString(),new BigDecimal("100"),MealType.LUNCH,null,null);var ingredients=new ArrayList<FoodEntryInputs.Ingredient>();for(int i=0;i<4;i++)ingredients.add(new FoodEntryInputs.Ingredient(UUID.randomUUID(),ref.getId().toString(),new BigDecimal("100"),null,null));var dish=new FoodEntryInputs.Dish(UUID.randomUUID(),"Synthetic four-ingredient dish",MealType.DINNER,"FULL_RECIPE",Map.of("kind","FRACTION","numerator",1,"denominator",2),ingredients,null);var input=new FoodEntryInputs.PreviewRequest(date,"Australia/Sydney",RecordSource.MANUAL,List.of(single,dish));proof=create.createBatchV2(owner.getId(),new FoodEntryInputs.BatchRequest(UUID.randomUUID(),date,input.zone(),input.source(),input.entries(),previews.previewNewBatch(owner.getId(),input).fingerprint()));}
 @Test void fiveLeavesProduceTwoRootsAndPaginationNeverSplitsTheDish(){var full=reads.listRoots(owner.getId(),date,date,null,"Australia/Sydney",0,20);assertEquals(2,full.totalMatches());assertEquals(2,full.results().size());assertEquals(5,full.results().stream().mapToInt(x->x.preview().leaves().size()).sum());assertEquals(new BigDecimal("3000.000"),full.results().stream().map(x->x.preview().totals().energyKj()).reduce(BigDecimal.ZERO,BigDecimal::add));var first=reads.listRoots(owner.getId(),date,date,null,null,0,1);var second=reads.listRoots(owner.getId(),date,date,null,null,1,1);assertTrue(first.hasMore());assertFalse(second.hasMore());assertNotEquals(first.results().getFirst().input().get("kind")+":"+first.results().getFirst().id(),second.results().getFirst().input().get("kind")+":"+second.results().getFirst().id());assertEquals(first,reads.listRoots(owner.getId(),date,date,null,null,0,1));assertTrue(List.of(first,second).stream().anyMatch(p->p.results().getFirst().preview().leaves().size()==4));}
 @Test void mealDateOwnerAndSoftDeletionFilterWholeRoots(){var dinner=reads.listRoots(owner.getId(),date,date,MealType.DINNER,null,0,20);assertEquals(1,dinner.results().size());assertEquals("DISH",dinner.results().getFirst().input().get("kind"));var other=FoodV2TestFixtures.owner(users,profiles);assertTrue(reads.listRoots(other.getId(),date,date,null,null,0,20).results().isEmpty());long id=Long.parseLong(dinner.results().getFirst().id());assertThrows(BusinessException.class,()->reads.getOwnedRoot(other.getId(),"dish",id));mutations.softDeleteOwnedRoot(owner.getId(),"dish",id,0L);assertEquals(1,reads.listRoots(owner.getId(),date,date,null,null,0,20).totalMatches());assertThrows(BusinessException.class,()->reads.getOwnedRoot(owner.getId(),"dish",id));assertTrue(reads.listRoots(owner.getId(),date.minusDays(1),date.minusDays(1),null,null,0,20).results().isEmpty());}
 @Test void legacyNameNullsQualityReferenceAndOriginalPhotoSourceArePreservedWithoutWrites(){long id=jdbc.queryForObject("INSERT INTO food_record(user_id,created_at,recorded_at,recorded_date,client_entry_id,source,food_name,quantity_grams,meal_type) VALUES(?,now(),now(),?,gen_random_uuid(),'PHOTO','Preserved synthetic legacy label',123.456,'SNACK') RETURNING id",Long.class,owner.getId(),date);var before=jdbc.queryForMap("SELECT * FROM food_record WHERE id=?",id);var root=reads.getOwnedRoot(owner.getId(),"single",id);assertEquals(DataQuality.LEGACY_UNVERIFIED,root.dataQuality());assertEquals("Preserved synthetic legacy label",root.displayName());assertEquals("IMAGE",root.source());assertNull(root.input().get("referenceId"));assertNull(root.preview().leaves().getFirst().referenceId());assertNull(root.preview().totals().energyKj());assertEquals("Preserved synthetic legacy label",root.componentDetails().getFirst().name());assertNull(root.componentDetails().getFirst().referenceId());assertEquals(new BigDecimal("123.456000000000"),root.input().get("quantityGrams"));assertEquals(before,jdbc.queryForMap("SELECT * FROM food_record WHERE id=?",id));var page=reads.listRoots(owner.getId(),date,date,MealType.SNACK,null,0,20);assertEquals(root,page.results().getFirst());}
 @Test void rangeIdentityAndPageBoundsRejectWithoutUnboundedReads(){for(int size:List.of(0,101))assertThrows(BusinessException.class,()->reads.listRoots(owner.getId(),date,date,null,null,0,size));assertThrows(BusinessException.class,()->reads.listRoots(owner.getId(),date,date,null,null,-1,20));assertThrows(BusinessException.class,()->reads.listRoots(owner.getId(),date.minusDays(366),date,null,null,0,20));assertThrows(BusinessException.class,()->reads.getOwnedRoot(owner.getId(),"unsafe",1L));assertTrue(reads.listRoots(owner.getId(),date,date,null,null,Integer.MAX_VALUE,100).results().isEmpty());}
 @Test void savedComponentNamesRemainOrderedAfterDeactivationAndRejectedCatalogueRename(){var root=reads.listRoots(owner.getId(),date,date,MealType.DINNER,null,0,20).results().getFirst();long dishId=Long.parseLong(root.id());jdbc.update("UPDATE food_record SET food_name='Saved ingredient '||dish_position WHERE dish_id=?",dishId);assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->jdbc.update("UPDATE food_reference SET display_name='Renamed current catalogue' WHERE id=?",ref.getId()));jdbc.update("UPDATE food_reference SET is_active=false WHERE id=?",ref.getId());var stored=reads.getOwnedRoot(owner.getId(),"dish",dishId);assertEquals(4,stored.componentDetails().size());for(int i=0;i<4;i++){assertEquals("Saved ingredient "+i,stored.componentDetails().get(i).name());assertEquals(stored.preview().leaves().get(i).clientEntryId(),stored.componentDetails().get(i).clientEntryId());assertEquals(ref.getId().toString(),stored.componentDetails().get(i).referenceId());}assertEquals(root.preview(),stored.preview());}
}
